// auth.go — the control plane's bearer token: setup, rotation, checks.
//
// There is no "open" mode any more. 18080 is reachable from the whole
// office LAN, so a node without a token is in SETUP state, not unprotected:
// every /api/* route answers 401 {"error":"setup_required"} until an
// operator completes POST /api/auth/setup.
//
// Setup needs two things, and the second is the point:
//
//   - the token, generated by the operator's browser (crypto.getRandomValues)
//     — the server only checks its format;
//   - a one-time setup code that only someone with root on the node (it is
//     in a 0600 file) or a seat in the ops Lark group can read.
//
// Without the code, whoever opened the console first after a deploy would
// own the node: setup is a race anyone on the LAN can enter. The code is
// regenerated on every process start in setup state and deleted once used.
//
// Token storage is a node-local 0600 file (api.token_file), not
// gateway.yaml: `make redeploy` copies the yaml to the operator's laptop.
// A legacy api.token in the yaml still works until the first rotation,
// which clears it so a deleted file cannot resurrect an old token.

package api

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base32"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/turnout-gateway/turnout-gateway/internal/config"
	"github.com/turnout-gateway/turnout-gateway/internal/configstore"
	"github.com/turnout-gateway/turnout-gateway/internal/notify"
)

// tokenPattern: "tgw_" + 32 random bytes in unpadded base64url. The prefix
// lets secret scanners and humans recognise a leaked token.
var tokenPattern = regexp.MustCompile(`^tgw_[A-Za-z0-9_-]{43}$`)

const (
	// setupCodeBytes → 100 bits after base32 (20 chars, shown in 5 groups).
	setupCodeBytes = 13
	// authBodyLimit caps /api/auth/* request bodies.
	authBodyLimit = 4 << 10
	// failWindow / failAlertAt: N failed checks from one source inside the
	// window raise one Lark alert. No lockout — tokens and setup codes are
	// ≥100 bits, so throttling buys nothing; the alert's value is knowing
	// someone is trying.
	failWindow  = 10 * time.Minute
	failAlertAt = 5
)

// Token sources reported by State / GET /api/auth/state.
const (
	TokenSourceNone = ""     // setup state
	TokenSourceFile = "file" // api.token_file
	TokenSourceYAML = "yaml" // legacy api.token
)

// AuthOptions configures NewAuth.
type AuthOptions struct {
	Cfg      *config.Config
	Store    *configstore.Store // clears the legacy yaml token on setup / rotate
	Notifier *notify.Notifier   // may be nil in tests
	// Fingerprint of the certificate the API presents, written next to the
	// setup code so one `sudo cat` gives the operator both things the
	// setup page asks them to check. Empty when TLS is off.
	Fingerprint string
	Now         func() time.Time
}

// Auth holds the live token and the setup state.
type Auth struct {
	opts      AuthOptions
	tokenPath string
	codePath  string

	token  atomic.Pointer[string] // "" = setup state
	source atomic.Pointer[string]

	mu            sync.Mutex // serializes setup / rotate / file writes
	setupCode     string     // only meaningful in setup state
	larkDelivered bool

	failMu   sync.Mutex
	failures map[string][]time.Time
	alerted  map[string]time.Time
}

// NewAuth loads the token (file, then legacy yaml). With neither, it enters
// setup state: generates a setup code, writes it to the 0600 code file and,
// when a Lark webhook is configured, sends it there.
func NewAuth(opts AuthOptions) (*Auth, error) {
	if opts.Now == nil {
		opts.Now = time.Now
	}
	a := &Auth{
		opts:      opts,
		tokenPath: opts.Cfg.API.TokenPath(),
		codePath:  opts.Cfg.API.SetupCodePath(),
		failures:  map[string][]time.Time{},
		alerted:   map[string]time.Time{},
	}
	tok, src, err := a.loadToken()
	if err != nil {
		return nil, err
	}
	a.setToken(tok, src)
	if tok != "" {
		// A stale code file from an earlier setup-state run must not
		// linger: it no longer opens anything, but it reads like it does.
		_ = os.Remove(a.codePath)
		return a, nil
	}
	if err := a.enterSetup(); err != nil {
		return nil, err
	}
	return a, nil
}

func (a *Auth) loadToken() (string, string, error) {
	data, err := os.ReadFile(a.tokenPath)
	switch {
	case err == nil:
		tok := strings.TrimSpace(string(data))
		if tok == "" {
			break // empty file = no token; fall through to yaml / setup
		}
		if !tokenPattern.MatchString(tok) {
			return "", "", fmt.Errorf("api: %s does not hold a valid token (want tgw_ + 43 base64url chars); delete it with --reset-api-token", a.tokenPath)
		}
		return tok, TokenSourceFile, nil
	case !errors.Is(err, os.ErrNotExist):
		return "", "", fmt.Errorf("api: read %s: %w", a.tokenPath, err)
	}
	if tok := strings.TrimSpace(a.opts.Cfg.API.Token); tok != "" {
		return tok, TokenSourceYAML, nil
	}
	return "", TokenSourceNone, nil
}

func (a *Auth) setToken(tok, src string) {
	a.token.Store(&tok)
	a.source.Store(&src)
}

func (a *Auth) current() string { return *a.token.Load() }

// Source reports where the live token came from ("" in setup state).
func (a *Auth) Source() string { return *a.source.Load() }

// InSetup reports whether the control plane is waiting for initialisation.
func (a *Auth) InSetup() bool { return a.current() == "" }

// SetupCodePath is where the operator reads the code (shown on the page).
func (a *Auth) SetupCodePath() string { return a.codePath }

// enterSetup mints a fresh setup code and publishes it to the code file
// and, if possible, Lark.
func (a *Auth) enterSetup() error {
	a.mu.Lock()
	defer a.mu.Unlock()
	code, err := newSetupCode()
	if err != nil {
		return err
	}
	a.setupCode = code
	var b strings.Builder
	fmt.Fprintf(&b, "setup_code=%s\n", code)
	if a.opts.Fingerprint != "" {
		fmt.Fprintf(&b, "tls_fingerprint_sha256=%s\n", a.opts.Fingerprint)
	}
	fmt.Fprintf(&b, "# One-time code for the console's 初始化 page. Regenerated on every\n# turnout-gateway start while no token is set; deleted once setup completes.\n")
	if err := os.MkdirAll(filepath.Dir(a.codePath), 0o755); err != nil {
		return fmt.Errorf("api: mkdir for setup code: %w", err)
	}
	if err := writeFileAtomic(a.codePath, []byte(b.String()), 0o600); err != nil {
		return err
	}
	// The journal gets the path, never the code: journald is readable by
	// the adm / systemd-journal groups, a wider audience than root.
	slog.Warn("api: no token configured — control plane is in SETUP mode; every /api/* answers 401 until an operator completes setup in the console",
		"setup_code_file", a.codePath)

	a.larkDelivered = false
	if n := a.opts.Notifier; n != nil {
		body := "setup code: " + code
		if a.opts.Fingerprint != "" {
			body += "\n证书指纹 SHA-256: " + a.opts.Fingerprint + "\n先在浏览器里核对指纹一致，再提交 setup code。"
		}
		err := n.SendPrivate(notify.Event{
			Time:     a.opts.Now(),
			Severity: notify.SeverityUrgent,
			Type:     "api_setup_code",
			Subject:  "控制面等待初始化（setup code，一次性）",
			Body:     body,
		})
		a.larkDelivered = err == nil
	}
	return nil
}

// newSetupCode returns 100 random bits as XXXX-XXXX-XXXX-XXXX-XXXX
// (base32, no padding). Compared case- and dash-insensitively.
func newSetupCode() (string, error) {
	buf := make([]byte, setupCodeBytes)
	if _, err := rand.Read(buf); err != nil {
		return "", fmt.Errorf("api: setup code: %w", err)
	}
	raw := base32.StdEncoding.WithPadding(base32.NoPadding).EncodeToString(buf)[:20]
	parts := make([]string, 0, 5)
	for i := 0; i < len(raw); i += 4 {
		parts = append(parts, raw[i:i+4])
	}
	return strings.Join(parts, "-"), nil
}

func normalizeCode(s string) string {
	s = strings.ToUpper(strings.TrimSpace(s))
	return strings.NewReplacer("-", "", " ", "").Replace(s)
}

// check reports whether r carries the live token. Constant-time over the
// token bytes; the length leak is the fixed token length.
func (a *Auth) check(r *http.Request) bool {
	tok := a.current()
	if tok == "" {
		return false
	}
	got, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
	if !ok {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(got), []byte(tok)) == 1
}

// wrap guards an /api/* handler.
func (a *Auth) wrap(h http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if a.InSetup() {
			writeJSON(w, http.StatusUnauthorized, map[string]string{
				"error": "setup_required",
				"hint":  "open /ui/ to initialise the control plane",
			})
			return
		}
		if !a.check(r) {
			a.recordFailure(r, "token")
			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
			return
		}
		h(w, r)
	}
}

// recordFailure logs a failed check and raises one Lark alert per source
// per window once failAlertAt failures accumulate.
func (a *Auth) recordFailure(r *http.Request, what string) {
	src := remoteIP(r)
	slog.Warn("api: authentication failed", "remote", src, "path", r.URL.Path, "check", what)
	now := a.opts.Now()
	a.failMu.Lock()
	hist := a.failures[src][:0]
	for _, t := range a.failures[src] {
		if now.Sub(t) < failWindow {
			hist = append(hist, t)
		}
	}
	hist = append(hist, now)
	a.failures[src] = hist
	alert := len(hist) >= failAlertAt && now.Sub(a.alerted[src]) >= failWindow
	if alert {
		a.alerted[src] = now
	}
	// Bound memory against a spray of sources.
	if len(a.failures) > 1024 {
		for k, v := range a.failures {
			if len(v) == 0 || now.Sub(v[len(v)-1]) >= failWindow {
				delete(a.failures, k)
			}
		}
	}
	a.failMu.Unlock()
	if alert {
		a.emit(notify.SeverityUrgent, "api_auth_failures",
			"控制面鉴权连续失败："+src,
			fmt.Sprintf("%s 在 %s 内 %d 次鉴权失败（%s），最近一次请求 %s。不会封禁；如果不是你在操作，查一下这台主机。",
				src, failWindow, len(hist), what, r.URL.Path))
	}
}

func (a *Auth) emit(sev notify.Severity, typ, subject, body string) {
	if a.opts.Notifier == nil {
		return
	}
	a.opts.Notifier.Emit(notify.Event{Time: a.opts.Now(), Severity: sev, Type: typ, Subject: subject, Body: body})
}

// storeToken persists tok to the token file and clears any legacy yaml
// token, then makes it live. Caller holds a.mu.
func (a *Auth) storeToken(tok string) error {
	if err := os.MkdirAll(filepath.Dir(a.tokenPath), 0o755); err != nil {
		return fmt.Errorf("mkdir: %w", err)
	}
	if err := writeFileAtomic(a.tokenPath, []byte(tok+"\n"), 0o600); err != nil {
		return err
	}
	if strings.TrimSpace(a.opts.Cfg.API.Token) != "" && a.opts.Store != nil {
		if err := a.opts.Store.Mutate(a.opts.Cfg, func(c *config.Config) error {
			c.API.Token = ""
			return nil
		}); err != nil {
			// The file already wins over the yaml, so the new token is in
			// force either way; the leftover only matters if the file is
			// deleted later. Say so and carry on.
			slog.Error("api: new token stored, but clearing the legacy api.token in gateway.yaml failed — remove it by hand",
				"err", err)
		}
	}
	a.setToken(tok, TokenSourceFile)
	return nil
}

func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, mode); err != nil {
		return fmt.Errorf("write %s: %w", tmp, err)
	}
	if err := os.Chmod(tmp, mode); err != nil {
		os.Remove(tmp)
		return fmt.Errorf("chmod %s: %w", tmp, err)
	}
	if err := os.Rename(tmp, path); err != nil {
		os.Remove(tmp)
		return fmt.Errorf("rename %s: %w", path, err)
	}
	return nil
}

// ── handlers ────────────────────────────────────────────────────────────

// AuthState is GET /api/auth/state. Unauthenticated, so it carries no
// secret: only which page the console should show and where the operator
// finds the code.
type AuthState struct {
	State         string `json:"state"` // "setup" | "active"
	SetupCodeHint string `json:"setup_code_hint,omitempty"`
	LarkDelivered bool   `json:"lark_delivered,omitempty"`
	// TokenSource is "file" or "yaml" when active; "yaml" makes the
	// console suggest a rotation into the node-local file.
	TokenSource string `json:"token_source,omitempty"`
}

func (a *Auth) handleState(w http.ResponseWriter, _ *http.Request) {
	if a.InSetup() {
		a.mu.Lock()
		delivered := a.larkDelivered
		a.mu.Unlock()
		writeJSON(w, http.StatusOK, AuthState{State: "setup", SetupCodeHint: a.codePath, LarkDelivered: delivered})
		return
	}
	// Source only once authenticated would be tidier, but the state route
	// is what the login page reads before it has a token; "file" vs "yaml"
	// says nothing an attacker can use.
	writeJSON(w, http.StatusOK, AuthState{State: "active", TokenSource: a.Source()})
}

func (a *Auth) handleSetup(w http.ResponseWriter, r *http.Request) {
	var dto struct {
		Token     string `json:"token"`
		SetupCode string `json:"setup_code"`
	}
	if err := decodeAuthBody(w, r, &dto); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	if !a.InSetup() {
		writeJSON(w, http.StatusConflict, map[string]string{"error": "already_initialized"})
		return
	}
	// Code first: a wrong code must not learn anything from token
	// validation (e.g. probing whether setup is reachable at all).
	want, got := normalizeCode(a.setupCode), normalizeCode(dto.SetupCode)
	if want == "" || subtle.ConstantTimeCompare([]byte(got), []byte(want)) != 1 {
		a.recordFailure(r, "setup_code")
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "invalid_setup_code"})
		return
	}
	if !tokenPattern.MatchString(dto.Token) {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_token_format", "hint": "want tgw_ + 43 base64url characters"})
		return
	}
	if err := a.storeToken(dto.Token); err != nil {
		slog.Error("api: setup could not store the token", "err", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "store token: " + err.Error()})
		return
	}
	a.setupCode = ""
	if err := os.Remove(a.codePath); err != nil && !errors.Is(err, os.ErrNotExist) {
		slog.Warn("api: setup done but the setup code file could not be removed", "path", a.codePath, "err", err)
	}
	src := remoteIP(r)
	slog.Info("api: control plane initialised — token set", "remote", src, "token_file", a.tokenPath)
	a.emit(notify.SeverityInfo, "api_setup_done", "控制面已初始化（token 已设置）",
		"来源 "+src+"。如果不是你本人操作，立即在节点上执行 turnout-gateway --reset-api-token 并重启。")
	w.WriteHeader(http.StatusNoContent)
}

func (a *Auth) handleRotate(w http.ResponseWriter, r *http.Request) {
	var dto struct {
		Token string `json:"token"`
	}
	if err := decodeAuthBody(w, r, &dto); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	if !tokenPattern.MatchString(dto.Token) {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_token_format", "hint": "want tgw_ + 43 base64url characters"})
		return
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	if subtle.ConstantTimeCompare([]byte(dto.Token), []byte(a.current())) == 1 {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "token_unchanged"})
		return
	}
	if err := a.storeToken(dto.Token); err != nil {
		slog.Error("api: rotate could not store the token", "err", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "store token: " + err.Error()})
		return
	}
	src := remoteIP(r)
	slog.Info("api: token rotated", "remote", src)
	a.emit(notify.SeverityInfo, "api_token_rotated", "控制面 token 已轮换",
		"来源 "+src+"。旧 token 立即失效；本机脚本读 token 文件，不受影响；笔记本上 export 的 TURNOUT_TOKEN 需要更新。")
	w.WriteHeader(http.StatusNoContent)
}

// Server-side shims so the routes read like every other guarded route.
func (s *Server) handleAuthRotate(w http.ResponseWriter, r *http.Request) {
	s.deps.Auth.handleRotate(w, r)
}

// handleAuthCheck is the console's login probe: 204 when the token is
// right, 401 otherwise (from the auth wrapper).
func (s *Server) handleAuthCheck(w http.ResponseWriter, _ *http.Request) {
	w.WriteHeader(http.StatusNoContent)
}

func decodeAuthBody(w http.ResponseWriter, r *http.Request, dst any) error {
	r.Body = http.MaxBytesReader(w, r.Body, authBodyLimit)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return fmt.Errorf("invalid json: %w", err)
	}
	return nil
}

func remoteIP(r *http.Request) string {
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

// ResetToken is the offline recovery path behind `turnout-gateway
// --reset-api-token`: it removes the token file and clears the legacy yaml
// token so the next start enters setup state. Needs root on the node by
// construction — that is the authority the setup code stands for.
func ResetToken(cfg *config.Config, store *configstore.Store) error {
	if err := os.Remove(cfg.API.TokenPath()); err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("remove %s: %w", cfg.API.TokenPath(), err)
	}
	if strings.TrimSpace(cfg.API.Token) != "" {
		if err := store.Mutate(cfg, func(c *config.Config) error {
			c.API.Token = ""
			return nil
		}); err != nil {
			return fmt.Errorf("clear api.token in gateway.yaml: %w", err)
		}
	}
	return nil
}
